{
  "avaliacoes": [
    {
      "id": "Ec60e3fa1dc1dd714",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "A parada programada de manutenção offshore é descrita como mobilização concentrada de grande número de trabalhadores especializados, em curto intervalo de tempo, para manutenção majoritariamente preventiva da planta industrial.",
          "trechos": [
            "Ec60e3fa1dc1dd714:0:700"
          ],
          "condicoes": [
            "No contexto de paradas programadas de manutenção na indústria petrolífera offshore."
          ],
          "limites": [
            "O trecho é introdutório e não detalha como preparar isolamentos, materiais, preservação ou testes pós-manutenção.",
            "A caracterização decorre do estudo apresentado, não de regra universal para toda parada."
          ]
        },
        {
          "proposicao": "O estudo analisa um caso de parada programada offshore desde o planejamento até o encerramento e compara práticas empresariais com um modelo teórico para sugerir melhorias ao projeto de parada.",
          "trechos": [
            "Ec60e3fa1dc1dd714:700:1400",
            "Ec60e3fa1dc1dd714:1400:2092"
          ],
          "condicoes": [
            "Baseado em estudo de caso ocorrido em 2015."
          ],
          "limites": [
            "Os trechos disponíveis não expõem as melhorias propostas nem suas evidências.",
            "Sem os capítulos analíticos, não é possível extrair critérios específicos aplicáveis ao recorte."
          ]
        }
      ]
    },
    {
      "id": "E9a05352e29bb2b86",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A seleção dos dados de manutenção a registrar deve evitar informações supérfluas ou sem uso definido, e o uso de computador para registro, manipulação e recuperação pode ser conveniente conforme a quantidade de equipamentos que demandem histórico.",
          "trechos": [
            "E9a05352e29bb2b86:0:700"
          ],
          "condicoes": [
            "No contexto de gestão de histórico de manutenção de instrumentos.",
            "Especialmente quando o volume de equipamentos justificar tratamento informatizado."
          ],
          "limites": [
            "O trecho não especifica estrutura mínima de registros para preparo de serviço, preservação ou testes pós-manutenção.",
            "A conveniência do uso de computador é contextual, não obrigação."
          ]
        },
        {
          "proposicao": "O trabalho é apresentado como análise e recomendações sobre gestão da manutenção de instrumentos, abrangendo estruturas de atividade, serviço e supervisão, treinamento, organização da manutenção preventiva, análise de custos, gestão de materiais, ferramentas e equipamentos e registros técnicos.",
          "trechos": [
            "E9a05352e29bb2b86:1392:2089"
          ],
          "condicoes": [
            "No escopo de grandes indústrias e especificamente de manutenção de instrumentos."
          ],
          "limites": [
            "O trecho resumido não detalha critérios operacionais de compatibilidade de materiais, isolamentos ou preservação.",
            "Por ser resumo, não comprova como cada elemento é tratado no corpo do documento."
          ]
        },
        {
          "proposicao": "A manutenção preventiva periódica é definida como atividade realizada por processos diretos ou indiretos nos equipamentos, obras ou instalações para assegurar condições de cumprir com eficácia, segurança e eficiência as funções incorporadas ao processo produtivo.",
          "trechos": [
            "E9a05352e29bb2b86:2089:2571"
          ],
          "condicoes": [
            "Apresentado como terminologia de manutenção no anexo citado."
          ],
          "limites": [
            "É definição conceitual geral; não descreve tarefas executivas de retorno ao serviço ou preservação de equipamentos inativos.",
            "O trecho disponível é parcial e não traz critérios de aceitação pós-intervenção."
          ]
        }
      ]
    },
    {
      "id": "E195c5225c680a40c",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A Engenharia de Manutenção participa ainda na fase de projeto e especificação dos equipamentos, incluindo verificação de atendimento às necessidades da planta, acompanhamento de testes de fabricação e condicionamento dos equipamentos antes da entrada em produção.",
          "trechos": [
            "E195c5225c680a40c:700:1392"
          ],
          "condicoes": [
            "No contexto organizacional descrito para a REFAP.",
            "Aplica-se à interface entre projeto, especificação, fabricação e preparação para colocação em produção."
          ],
          "limites": [
            "O trecho não detalha procedimentos executivos de preservação, isolamentos ou testes pós-manutenção em FPSO.",
            "A referência é a colocação em produção, não necessariamente retorno ao serviço após intervenção de manutenção."
          ]
        },
        {
          "proposicao": "Decisões de especificação e manutenção são apoiadas por procedimentos e padrões de engenharia do sistema normativo interno, e ações sem cobertura documental ou em desacordo exigem análise de engenharia e aprovação de profissional habilitado.",
          "trechos": [
            "E195c5225c680a40c:1392:2086"
          ],
          "condicoes": [
            "No ambiente normativo interno citado pela fonte.",
            "Quando a ação pretendida não estiver coberta pelos requisitos documentais existentes ou divergir deles."
          ],
          "limites": [
            "O texto não reproduz os requisitos nem permite inferir seu conteúdo específico para isolamentos, materiais ou retorno ao serviço.",
            "Trata-se de arranjo documental da instalação descrita, não de requisito brasileiro geral."
          ]
        },
        {
          "proposicao": "O acompanhamento da integridade física e do estado geral dos equipamentos é priorizado conforme importância para o processo, tipo e condição do fluido e impactos potenciais em segurança, meio ambiente e finanças em caso de falha.",
          "trechos": [
            "E195c5225c680a40c:1392:2086",
            "E195c5225c680a40c:2086:2320"
          ],
          "condicoes": [
            "Principalmente para equipamentos e sistemas em contato direto com fluidos de processo."
          ],
          "limites": [
            "O trecho trata de monitoramento e integridade, mas não define critérios específicos para seleção de redundância, preservação em standby ou obsolescência.",
            "As frequências de acompanhamento não são informadas."
          ]
        }
      ]
    },
    {
      "id": "E3620f0698062808a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Análises de RAMS são apresentadas como base para decisões em operação, fabricação e engenharia offshore, e dependem de dados de confiabilidade e manutenção para análise do desempenho da planta ou do sistema.",
          "trechos": [
            "E3620f0698062808a:0:695",
            "E3620f0698062808a:695:1395"
          ],
          "condicoes": [
            "No contexto das indústrias de petróleo, gás natural e petroquímica."
          ],
          "limites": [
            "O trecho não define como essas decisões se traduzem em procedimentos de preparação, isolamentos ou testes pós-manutenção.",
            "A utilidade é de suporte analítico geral."
          ]
        },
        {
          "proposicao": "As informações de falhas, mecanismos de falha e manutenção precisam ser transmitidas entre áreas de uma mesma companhia e entre companhias, e dados coletados ao longo de vários anos devem ser acumulados para dar confiança às análises e apoiar decisões relevantes.",
          "trechos": [
            "E3620f0698062808a:695:1395"
          ],
          "condicoes": [
            "Quando se busca análise de resultados com maior confiança e suporte a decisões."
          ],
          "limites": [
            "O trecho não especifica critérios de qualidade, taxonomia ou campos mínimos para registros do recorte.",
            "Não há indicação de requisito obrigatório de compartilhamento."
          ]
        },
        {
          "proposicao": "A coleta de dados exige investimento, padronização e gerenciamento eletrônico efetivo, e esse custo pode ser reduzido por cooperação entre indústrias; a ISO citada é mencionada com objetivo de padronizar a coleta e as informações relevantes, e são citados bancos de dados como OREDA, Well Master e Subsea Master.",
          "trechos": [
            "E3620f0698062808a:1395:2089"
          ],
          "condicoes": [
            "No contexto de bancos de dados de confiabilidade e manutenção para o setor."
          ],
          "limites": [
            "Os números da norma e demais dados específicos estão apagados.",
            "O trecho não detalha conteúdo operacional desses bancos nem sua aplicação direta a execução, preservação e retorno."
          ]
        }
      ]
    },
    {
      "id": "E3e1b78da365950c5",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": []
    },
    {
      "id": "E04a8af64aa7f7387",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O texto associa um bom programa de confiabilidade e manutenabilidade ao controle e registro de todas as atividades e eventos relevantes, não apenas à programação e execução de tarefas.",
          "trechos": [
            "E04a8af64aa7f7387:0:696"
          ],
          "condicoes": [
            "No contexto de entendimento do comportamento de equipamentos na indústria de óleo e gás."
          ],
          "limites": [
            "Não define quais atividades e eventos devem ser registrados para o recorte específico de execução, preservação e retorno ao serviço.",
            "É formulação geral de gestão, sem procedimento operacional."
          ]
        },
        {
          "proposicao": "A ISO citada tem por objetivo prover um ponto de vista comum para facilitar a coleta e troca de dados de confiabilidade e manutenção entre companhias de petróleo, petroquímica e gás natural.",
          "trechos": [
            "E04a8af64aa7f7387:696:1391",
            "E04a8af64aa7f7387:1391:2088"
          ],
          "condicoes": [
            "No escopo da norma internacional mencionada na fonte."
          ],
          "limites": [
            "A fonte não mostra o conteúdo operacional da norma nem seu status como requisito no Brasil.",
            "A utilidade é principalmente de controle e padronização de dados, não de instrução direta sobre isolamentos ou preservação."
          ]
        },
        {
          "proposicao": "Na segunda edição da ISO mencionada, o anexo B sobre interpretação e notação de parâmetros de falha e manutenção passou de recomendação a conteúdo normativo, enquanto os demais anexos permaneceram como recomendações de uso de dados.",
          "trechos": [
            "E04a8af64aa7f7387:1391:2088"
          ],
          "condicoes": [
            "Conforme a descrição histórica da evolução da edição citada."
          ],
          "limites": [
            "O trecho não permite reconstruir numeração, datas apagadas ou conteúdo técnico dos anexos.",
            "A mudança editorial não implica, por si, requisito de aplicação ao recorte em FPSO."
          ]
        }
      ]
    }
  ],
